-- GridMind POC-01. Reference planning data only; NO customer vehicle, private data or actual telemetry.
-- Do not insert scooter into public.machine_types: it is not an industrial machine taxonomy record.
-- Source of truth: data/poc/scooter-stationary-v1.json (commit-matched by validation script).
create table if not exists public.poc_asset_archetypes (
  archetype_id text primary key,
  display_name text not null,
  schema_version text not null,
  classification text not null check (classification = 'poc_reference_only'),
  drivetrain_variant text not null check (drivetrain_variant = 'unknown'),
  validation_status text not null check (validation_status = 'candidate_unvalidated'),
  manufacturer text,
  model text,
  measurement_execution_status text not null check (measurement_execution_status = 'not_started'),
  physical_sensors_installed integer not null default 0 check (physical_sensors_installed = 0),
  created_at timestamptz not null default now()
);
create table if not exists public.poc_asset_components (
  archetype_id text not null references public.poc_asset_archetypes(archetype_id) on delete restrict,
  component_key text not null,
  display_name text not null,
  applies_to text not null check (applies_to in ('both','petrol','electric')),
  scope_note text not null,
  validation_status text not null check (validation_status = 'archetype_candidate'),
  primary key (archetype_id, component_key)
);
create table if not exists public.poc_measurement_candidates (
  archetype_id text not null references public.poc_asset_archetypes(archetype_id) on delete restrict,
  measurement_key text not null,
  display_name text not null,
  component_key text not null,
  applies_to text not null check (applies_to in ('both','petrol','electric')),
  source_class text not null check (source_class in ('phone','manual','existing_record','professional_external')),
  data_origin text not null check (data_origin in ('independent_test_rig','existing_record','future_qualified_scooter')),
  phase integer not null check (phase between 0 and 2),
  unit text not null,
  instrument_class text not null,
  what_it_can_establish text not null,
  what_it_cannot_establish text not null,
  requires_qualified_professional boolean not null,
  installation_status text not null check (installation_status = 'not_installed'),
  validation_status text not null check (validation_status = 'candidate_not_tested'),
  primary key(archetype_id, measurement_key),
  foreign key (archetype_id, component_key) references public.poc_asset_components(archetype_id,component_key) on delete restrict,
  check (source_class <> 'professional_external' or (phase = 2 and requires_qualified_professional)),
  check (data_origin <> 'independent_test_rig' or (phase = 0 and source_class = 'phone'))
);
-- Every POC reference table is explicitly read-only to browser roles.
alter table public.poc_asset_archetypes enable row level security;
alter table public.poc_asset_components enable row level security;
alter table public.poc_measurement_candidates enable row level security;
revoke all on public.poc_asset_archetypes,public.poc_asset_components,public.poc_measurement_candidates from public,anon,authenticated;
grant select on public.poc_asset_archetypes,public.poc_asset_components,public.poc_measurement_candidates to authenticated;
create policy "authenticated read POC archetypes" on public.poc_asset_archetypes for select to authenticated using (true);
create policy "authenticated read POC components" on public.poc_asset_components for select to authenticated using (true);
create policy "authenticated read POC candidates" on public.poc_measurement_candidates for select to authenticated using (true);
